-- Reverses migration/V2__curriculum_seed.sql: the 22 curriculum topics it inserted
-- (8 top-level Jahrgangsstufen + 14 Lernbereich sub-topics) and the concept<->topic
-- mappings hung off them. Later migrations (V11, V12) only add columns to and
-- backfill these same rows, never change which ids exist, so deleting by id here
-- is exact. V5's curriculum_code_examples rows reference two of these topics by
-- id too; undo those first (see undo/V5) or they cascade-delete along with them.

DELETE FROM concept_curriculum_topic
WHERE topic_id IN (
    'a0000000-0000-0000-0000-000000000009',
    'a0000000-0000-0000-0000-000000000010',
    'a0000000-0000-0000-0000-000000000011',
    '7a3c9e2f-8b4d-4a1c-9f6e-3d5b7c1e8f02',
